import sys, json, os, time, random
import numpy as np

def read_instance(path):
    with open(path) as f:
        data = json.load(f)
    return np.array(data["A"], dtype=int), np.array(data["B"], dtype=int)

def cost(p, A, B):
    return int(np.sum(A * B[p][:, p]))

def local_search(p, A, B, budget):
    start = time.time()
    n = len(p)
    best_p = p.copy()
    best_cost = cost(p, A, B)
    while True:
        elapsed = time.time() - start
        if elapsed >= budget:
            break
        # occasional random restart
        if random.random() < 0.05:
            p = list(range(n))
            random.shuffle(p)
            cur_cost = cost(p, A, B)
        else:
            i, j = random.sample(range(n), 2)
            p[i], p[j] = p[j], p[i]
            cur_cost = cost(p, A, B)
            if cur_cost > best_cost:
                p[i], p[j] = p[j], p[i]  # revert
        if cur_cost < best_cost:
            best_cost = cur_cost
            best_p = p.copy()
    return best_p

def main():
    if len(sys.argv) < 3:
        return
    instance_path = sys.argv[1]
    budget = float(sys.argv[2])
    env_budget = os.getenv("QAP_TIME_LIMIT_S")
    if env_budget:
        budget = min(budget, float(env_budget))
    A, B = read_instance(instance_path)
    n = A.shape[0]
    p = list(range(n))
    random.shuffle(p)
    best_p = local_search(p, A, B, budget)
    print("PERMUTATION: " + " ".join(str(x+1) for x in best_p))

if __name__ == "__main__":
    main()
